const counter = (() => {
  let count = 0;

  return {
    add: () => {
      count = count + 1;
    },
    get: () => count,
  };
})();

function getCount() {
  counter.add();
  counter.add();

  return counter.get();
}

function runCounter(start, step) {
  const counter = (() => {
    let count = start;

    return {
      add: () => {
        count = count + step;
      },
      get: () => count,
    };
  })();

  counter.add();
  counter.add();

  return counter.get();
}
